package com.loopers.interfaces.consumer
import org.apache.kafka.clients.admin.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.StringDeserializer;import org.testcontainers.kafka.KafkaContainer;import org.testcontainers.utility.DockerImageName;import java.util.Properties
class KafkaExperimentSupport:AutoCloseable{val broker=KafkaContainer(DockerImageName.parse("apache/kafka-native:3.8.0")).also{it.start()};fun topic(name:String,partitions:Int){Admin.create(mapOf(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG to broker.bootstrapServers)).use{it.createTopics(listOf(NewTopic(name,partitions,1))).all().get()}};fun consumer(group:String,id:String):KafkaConsumer<String,String>{val p=Properties();p[ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG]=broker.bootstrapServers;p[ConsumerConfig.GROUP_ID_CONFIG]=group;p[ConsumerConfig.CLIENT_ID_CONFIG]=id;p[ConsumerConfig.GROUP_INSTANCE_ID_CONFIG]=id;p[ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG]="false";p[ConsumerConfig.AUTO_OFFSET_RESET_CONFIG]="earliest";p[ConsumerConfig.PARTITION_ASSIGNMENT_STRATEGY_CONFIG]="org.apache.kafka.clients.consumer.RangeAssignor";p[ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG]=StringDeserializer::class.java;p[ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG]=StringDeserializer::class.java;return KafkaConsumer(p)};override fun close(){broker.stop()}}
